CREATE TABLE IF NOT EXISTS ext_host_host_version(version INTEGER NOT NULL);
INSERT INTO ext_host_host_version SELECT 1 WHERE NOT EXISTS(SELECT 1 FROM ext_host_host_version);
CREATE TABLE IF NOT EXISTS ext_host_publishers(id TEXT PRIMARY KEY, public_key TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_host_publisher_source_tickets(publisher TEXT PRIMARY KEY REFERENCES ext_host_publishers(id) ON DELETE CASCADE, ticket TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_host_packages(digest TEXT PRIMARY KEY,plugin_id TEXT NOT NULL,version TEXT NOT NULL,manifest TEXT NOT NULL,public_key TEXT,bytes INTEGER NOT NULL,removed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ext_host_selections(plugin_id TEXT PRIMARY KEY,digest TEXT NOT NULL,previous TEXT,enabled INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'installed',error TEXT,epoch INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1,source TEXT,connection TEXT,report INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ext_host_private_settings(digest TEXT PRIMARY KEY,settings TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_host_provider_presets(plugin_id TEXT NOT NULL,digest TEXT NOT NULL,preset TEXT NOT NULL,provider_id TEXT NOT NULL,PRIMARY KEY(plugin_id,digest,preset));
CREATE TABLE IF NOT EXISTS ext_host_operations(id TEXT PRIMARY KEY,digest TEXT NOT NULL,phase TEXT NOT NULL,review TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_host_audit(id INTEGER PRIMARY KEY,plugin_id TEXT NOT NULL,digest TEXT NOT NULL,action TEXT NOT NULL,at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS ext_host_audit_retention AFTER INSERT ON ext_host_audit BEGIN DELETE FROM ext_host_audit WHERE id <= NEW.id-10000; END;
CREATE TABLE IF NOT EXISTS ext_adv_extension_version(version INTEGER NOT NULL);
INSERT INTO ext_adv_extension_version SELECT 1 WHERE NOT EXISTS(SELECT 1 FROM ext_adv_extension_version);
CREATE TABLE IF NOT EXISTS ext_adv_resources(plugin_id TEXT PRIMARY KEY,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_adv_protocols(provider_id TEXT PRIMARY KEY,plugin_id TEXT NOT NULL,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_adv_plans(id TEXT PRIMARY KEY,plugin_id TEXT NOT NULL,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_adv_connector_calls(id INTEGER PRIMARY KEY,plugin_id TEXT NOT NULL,identity TEXT NOT NULL,record TEXT NOT NULL,UNIQUE(plugin_id,identity));
CREATE TRIGGER IF NOT EXISTS ext_adv_call_retention AFTER INSERT ON ext_adv_connector_calls BEGIN DELETE FROM ext_adv_connector_calls WHERE id<=NEW.id-10000;END;
CREATE TABLE IF NOT EXISTS ext_source_full_version(version INTEGER NOT NULL);
INSERT INTO ext_source_full_version SELECT 1 WHERE NOT EXISTS(SELECT 1 FROM ext_source_full_version);
CREATE TABLE IF NOT EXISTS ext_source_full_packages(digest TEXT PRIMARY KEY,plugin_id TEXT NOT NULL,record TEXT NOT NULL,removed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ext_source_full_selections(plugin_id TEXT PRIMARY KEY,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_source_full_reviews(id TEXT PRIMARY KEY,record TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ext_source_full_projections(plugin_id TEXT PRIMARY KEY,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_source_full_hidden_projects(id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS ext_source_full_saved_sources(plugin_id TEXT PRIMARY KEY,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_domain_domain_version(version INTEGER NOT NULL);
INSERT INTO ext_domain_domain_version SELECT 1 WHERE NOT EXISTS(SELECT 1 FROM ext_domain_domain_version);
CREATE TABLE IF NOT EXISTS ext_domain_source_consents(plugin_id TEXT PRIMARY KEY,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_domain_source_projections(plugin_id TEXT PRIMARY KEY,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_policy_policy_meta(format INTEGER NOT NULL);
INSERT INTO ext_policy_policy_meta SELECT 1 WHERE NOT EXISTS(SELECT 1 FROM ext_policy_policy_meta);
CREATE TABLE IF NOT EXISTS ext_policy_policy_packages(digest TEXT PRIMARY KEY,id TEXT NOT NULL,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_policy_policy_selections(id TEXT PRIMARY KEY,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_policy_policy_reviews(id TEXT PRIMARY KEY,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_policy_policy_controls(scope TEXT PRIMARY KEY,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_policy_policy_bindings(scope TEXT NOT NULL,version TEXT NOT NULL,record TEXT NOT NULL,PRIMARY KEY(scope,version));
CREATE TABLE IF NOT EXISTS ext_policy_policy_intents(id TEXT PRIMARY KEY,record TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ext_obj_object_grants(plugin_id TEXT NOT NULL,slot_id TEXT NOT NULL,record TEXT NOT NULL,PRIMARY KEY(plugin_id,slot_id));
CREATE TABLE IF NOT EXISTS ext_policy_policy_scope_recoveries(id TEXT PRIMARY KEY,record TEXT NOT NULL);
